    ('skills/horizons-orbital-mechanics/SKILL.md', 'line 218: ## Where the Check Lives, and What It Compare',
     (
         '\n'
         '## Reference Frame Diagnostic\n'
     ),
     (
         '\n'
         '## Where the Check Lives, and What It Compares (L-395, L-431 build 3)\n'
         '\n'
         "Moved 2026-10-14 from the website's Daily Run into the orrery (Tony,\n"
         '2026-10-12: "the orrery stores and serves the data not the other way\n'
         'around"). The move\'s brief is\n'
         'documentation/HANDOFF_L395_horizons_check_move_brief_20261012.md; the\n'
         "build's record, documentation/HANDOFF_L431_build3_website_20261014.md.\n"
         '\n'
         "- `horizons_check.py` is a GENERATOR row of the orrery's maintenance\n"
         '  run, just before the objects export, so the export carries the dates\n'
         '  it writes. `check_horizons_confirmations.py` is a CHECKER row that\n'
         '  reads what it wrote, offline. The website keeps an offline check of\n'
         '  its own, `tools/check_horizons_confirmations.py`, which reads the\n'
         '  dates from the pulled export and goes red, naming the objects, on the\n'
         '  day one turns 30 days old.\n'
         '- Only what is due is asked: a part of an entry never confirmed, one\n'
         '  confirmed 30 days ago or more, or one that has changed since (the\n'
         '  record keeps what was confirmed, so a change shows). On most runs it\n'
         '  asks JPL nothing. An identity or a period is asked again from day 25\n'
         '  ("renewing"): the website goes red at day 30 and sees a new date only\n'
         "  after the orrery's push and its own pull, so asking at day 30 would\n"
         '  leave it red every cycle. The offline checker passes a renewing\n'
         '  confirmation until day 30. The data sheets keep 30.\n'
         "- A small body's COMMAND ends with ';', sent as %3B, as JPL's own\n"
         "  examples send it; a bare ';' in a URL can end the parameter early.\n"
         '- The period: for an entry whose period was fetched, one ELEMENTS query\n'
         "  as the orrery asked it -- the same COMMAND, CENTER the period's own\n"
         "  centre, TLIST the period's own date written as a calendar Julian day,\n"
         "  OUT_UNITS AU-D -- and JPL's PR must lie within the period's own error\n"
         '  of the period the website prints. A typed period, or none, is not\n'
         '  compared; the line names it as not from JPL.\n'
         '- Any failure to get JPL\'s answer is "could not reach JPL". It never\n'
         '  passes, nothing is recorded for that part, it stays due, and the run\n'
         '  asks JPL nothing more that day. The verdict says UNREACHABLE by name:\n'
         '  the convention for every row that needs the network.\n'
         '- The data sheets: every spacecraft in the list (an id starting with\n'
         "  '-') has its Horizons data sheet re-read on the same 30-day cycle,\n"
         '  into `data/spacecraft_sheets.json`. Red only where a row of\n'
         '  `constants_new.py` quotes a figure from the sheet and the sheet no\n'
         '  longer gives it (Tony\'s option A, 2026-10-12: "the row claims the\n'
         '  figure, not the page"); a patch to the row clears it. A sheet whose\n'
         '  "Revised:" date moved and whose figure did not is noted, not red.\n'
         '  Nothing here edits a row.\n'
         '- The thirteen identity confirmations of 2026-10-10 were carried over\n'
         '  with their dates, so the move asked JPL nothing. The offline tests run\n'
         "  on JPL's recorded answers,\n"
         '  `documentation/worksheets/horizons_answers_L395.json`. Its identity\n'
         "  answers are JPL's own; its elements and data-sheet answers were\n"
         "  written in JPL's format by the build, which could not reach JPL, and\n"
         '  the file says so for each, so the first live run is the real test of\n'
         '  the parsing. The same file freezes the inputs the test runs on (the\n'
         '  three cache entries, the carried confirmations, the seeded sheets):\n'
         '  a test that read the live records would fail on the day the check\n'
         '  first worked.\n'
         '\n'
         '## Reference Frame Diagnostic\n'
     )),
