         '\n'
         "## The Daily Run's Steps [QUALITY]\n"
         '\n'
         "`daily_run.py`, Tony's design of 2026-09-27 (L-281), is three steps\n"
         'since 2026-10-14: the guest book updater, this builder with no flags,\n'
         'and the gallery maintenance run offline. A step that reports a problem\n'
         'does not stop the next; nothing in it commits or pushes. The Horizons\n'
         'check was its step 2 from 2026-10-10 to 2026-10-14 and moved into the\n'
         "orrery's maintenance run beside the objects export (L-395; Tony,\n"
