        '        json.dump(cache, h)\n'
        '    rows = {"VOYAGER_1_POINTING_RA_2030_ARCSEC": 1.701,\n'
        '            "VOYAGER_1_POINTING_DEC_2030_ARCSEC": 1.535,\n'
        '            "VOYAGER_2_POINTING_RA_2030_ARCSEC": 4.718,\n'
        '            "VOYAGER_2_POINTING_DEC_2030_ARCSEC": 3.715}\n'
        '    with open(os.path.join(tmp, "data", "constants_export.json"), "w") as h:\n'
        '        json.dump({"rows": {k: {"value": v, "read": [\n'
