        '{\n'
        '  "_comment": "JPL Horizons answers for test_horizons_check.py (L-395), keyed by the exact query the check makes. Answers from 2026-10-07 were fetched by Tony in his browser and recorded in the orrery\'s documentation/HORIZONS_ANSWERS_L395_20261007.md. Answers from 2026-10-10 were fetched by this build session through the chat\'s web-fetch tool, which passes a page through a reading model: their field lines are JPL\'s, their layout is rebuilt. Each answer\'s source is in sources. Re-fetched 2026-10-10: every 2026-10-07 answer used here read the same except Encke\'s record (G3), which JPL re-solved in place (solution date 2026-Oct-09); the recorded 2026-10-07 text is kept. Moved from the gallery\'s documentation/ into the orrery\'s documentation/worksheets/ by L-431 build 3 (2026-10-14), with the check. That build added answers for the period\'s elements queries and the spacecraft data sheets; every one it added is CONSTRUCTED, says so in sources, and is not JPL\'s text.",\n'
