def _zone_hit(text, pos, length):
    spans = []
    for a, b in ZONES:
        if a in text and b in text:
            spans.append((text.index(a), text.index(b) + len(b)))
    if MARKER in text:
        spans.append((text.index(MARKER), len(text)))
    for s, e in spans:
        if pos < e and pos + length > s:
            return True
    return False


def apply():
    print('%s' % os.path.basename(__file__))
    print('Running in: %s' % ROOT)
    print()
    for f in MUST_EXIST:
        if not os.path.exists(os.path.join(ROOT, f)):
            print('ERROR: %s is not here. Save this script in the orrery repo\'s ROOT '
                  'folder and run it there. NOTHING was written.' % f)
            return None
    for f in CREATED:
        if os.path.exists(os.path.join(ROOT, f)):
            print('ERROR: %s already exists; this patch has run. NOTHING was written.' % f)
            return None
    texts, crlf, done = {}, set(), []
    for f, label, old, new in EDITS:
        path = os.path.join(ROOT, f)
        if f not in texts:
            if not os.path.exists(path):
                print('ERROR: %s not found in %s. NOTHING was written.' % (f, ROOT))
                return None
            raw = open(path, 'rb').read()
            if b'\r\n' in raw:
                crlf.add(f)
            texts[f] = raw.replace(b'\r\n', b'\n').decode('utf-8')
        t = texts[f]
        n = t.count(old)
        if n != 1:
            print('ANCHOR FAIL  %-45s %s (found %d times, expected 1). NOTHING was written.'
                  % (f, label, n))
            return None
        if _zone_hit(t, t.index(old), len(old)):
            print('ANCHOR FAIL  %-45s %s lies in a generated zone or below the run-record '
                  'marker. NOTHING was written.' % (f, label))
            return None
        texts[f] = t.replace(old, new)
        done.append((f, label))
    for f, t in list(texts.items()) + list(CREATED.items()):
        if any(ord(c) > 127 for c in t):
            print('ERROR: %s would hold non-ASCII after this patch. NOTHING was written.' % f)
            return None
    for f, t in texts.items():
        with open(os.path.join(ROOT, f), 'w', encoding='utf-8', newline='') as h:
            h.write(t)
    for f, t in CREATED.items():
        d = os.path.dirname(os.path.join(ROOT, f))
        if d and not os.path.isdir(d):
            os.makedirs(d)
        with open(os.path.join(ROOT, f), 'w', encoding='utf-8', newline='') as h:
            h.write(t)
    for f, label in done:
        print('ok  %-45s %s' % (f, label))
    for f in CREATED:
        print('ok  %-45s created' % f)
    for f in sorted(crlf):
        print('note: %s was CRLF in the working copy; written LF' % f)
    print()
    print('patch applied (%d edits in %d files, %d files created)'
          % (len(done), len(texts), len(CREATED)))
    print('Stamps updated: the docstrings of every edited module, the three skills,')
    print('the protocol (v3.96), the ledger, Where We Are.')
    return True


def main():
    if not apply():
        return 1
    print()
    print('NEXT (the handoff has the whole run order, with what each step prints):')
    print('  1. Run orrery_maintenance_run.py. It needs the internet today: the')
    print('     Horizons check asks JPL about the three periods it has never')
    print('     confirmed (Mercury, Jupiter, Encke). Expect "Horizons check" to read')
    print('     PASS and every gating checker to pass. UNREACHABLE means JPL could')
    print('     not be reached: run it again later, before you commit.')
    print('  2. Move this script, and patch_L431_10_brief_both_sets_20261013.py if it')
    print('     is still in this folder, into documentation/. Commit and push.')
    print('  3. Then the gallery: tools/pull_objects_export.py, then')
    print('     patch_L431_12_website_gallery_20261014.py. Then back here for')
    print('     patch_L431_13_dashboard_buttons_20261014.py.')
    return 0


if __name__ == '__main__':
    sys.exit(main())
